USERS = {"carol", "alice", "bob"}

def list_users():
    """Return all users, in no particular order."""
    return sorted(USERS)  # alphabetical today, by accident

print(list_users()[0])  # a caller now depends on "alice" coming first

cart = [{"price": 5, "qty": 2}, {"price": 3, "qty": 1}]
# Before: the totaling loop sits inline
total = 0
for item in cart:
    total += item["price"] * item["qty"]
print(total * 1.2)

# After: same behavior, with the loop extracted and named
def subtotal(cart):
    return sum(i["price"] * i["qty"] for i in cart)

print(subtotal(cart) * 1.2)
